<script id="rampart-strategy">
function createStrategy() {
  const weapons = {
    bolt:[26,8,0], cannon:[60,24,90], frost:[10,12,0],
    lance:[180,36,0], flak:[40,10,70]
  };
  const layout = ['"'cannon','cannon','cannon','cannon','cannon','flak','cannon','cannon',
    'flak','lance','flak','cannon','cannon','flak','flak','flak'];
  const costs = {bolt:50,cannon:90,frost:70,lance:120,flak:80};
  const priority = [1.12,1.05,1.06,1,0.94,1.24,1.03,0.92,1.24,0.9,1.2,1.05,1.06,1.16,0.93,1.02];

  function plan(state) {
    let gold = state.gold;
    const slots = state.slots.map(s => s.turret ? {...s.turret} : null);
    const actions = [];
    if (state.wave === 1) return [{op:'build',slot:0,type:'cannon'},{op:'build',slot:2,type:'lance'}];
    const flyers = state.enemies.filter(e => e.air);
    const airThreat = flyers.some(e => e.remaining < 1100) || state.nextWave.filter(t => t === 'wisp').length >= 3;
    const firstFlak = slots[5] || slots[8] || slots[10] || slots[15];
    if (state.wave < 5 && "'!airThreat && flyers.length === 0) return actions;
    while (actions.length < 32) {
      let best = null;
      for (let slot = 0; slot < slots.length; slot++) {
        const current = slots[slot];
        const type = current ? current.type : layout[slot];
        const tier = current ? current.tier : 0;
        const cost = costs[type] * (tier === 2 ? 2 : 1);
        if (tier === 3 || cost > gold || (type === '"'flak' && state.wave < 3)) continue;
        let value = priority[slot] * [1,0.86,0.57][tier];
        if (type === 'flak') {
          value *= airThreat ? 1.16 : 0.76;
          if ("'!firstFlak && !actions.some(a => a.type === '"'flak') && airThreat) value *= 2;
        } else if (state.wave < 12 && slot <= 3) value *= 1.22;
        if ("'!best || value > best.value) best = {slot,type,tier,cost,value};
      }
      if (!best) break;
      const {slot,type,tier,cost} = best;
      actions.push(tier ? {op:'"'upgrade',slot} : {op:'build',slot,type});
      slots[slot] = {type,tier:tier+1};
      gold -= cost;
    }
    return actions;
  }

  function target(turret, candidates) {
    const [base, , radius] = weapons[turret.type];
    let damage = base;
    for (let i = 1; i < turret.tier; i++) damage = Math.floor(damage * 1.6);
    let best = -Infinity, id = candidates[0].id;
    for (const enemy of candidates) {
      let value = 0;
      for (const other of radius ? candidates : [enemy]) {
        if (radius && (enemy.x-other.x)**2 + (enemy.y-other.y)**2 > radius*radius) continue;
        const hit = Math.max(1, damage - (turret.type === 'lance' ? 0 : other.armor));
        const urgency = 1 + Math.max(0, 850 - other.remaining) / 220;
        const finish = hit >= other.hp ? (other.type === 'mender' ? 39 : 15) : 0;
        value += (Math.min(other.hp,hit) + finish) * urgency * (other.type === 'mender' ? 1.45 : 1);
      }
      value += 0.0001 * (4600-enemy.remaining);
      if (value > best) { best = value; id = enemy.id; }
    }
    return id;
  }
  return {plan,target};
}
</script>
<script id=\"rampart-sim\">
function rampartSimulate(createStrategy, seed, maxTicks, record) {
  const paths = [
    [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],
    [[0,6],[21,6],[21,11],[23,11]]
  ].map(route => route.map(([x,y]) => [100*x+50,100*y+50]));
  const lengths = [4600,2800];
  // The lane's listed length is the leak threshold, before the final bend ends.
  lengths[1] = 2600;
  const types = [
    ['grunt',60,10,4,1,0,1,10], ['runner',40,20,4,1,0,2,4],
    ['wisp',50,12,6,2,1,3,3], ['brute',150,6,9,3,0,4,3],
    ['splitter',90,8,6,2,0,6,2], ['mender',70,8,7,2,0,8,1],
    ['splitling',0,12,1,1,0,Infinity,0]
  ];
  const names = ['bolt','cannon','frost','lance','flak'];
  const weapons = [
    [50,26,8,300,0,0,0,3], [90,60,24,260,90,0,0,1],
    [70,10,12,240,0,30,0,3], [120,180,36,360,0,0,1,1],
    [80,40,10,320,70,0,0,2]
  ];
  const slots = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],
    [14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]]
    .map(([x,y],slot) => ({slot,x:100*x+50,y:100*y+50,turret:null}));
  const strategy = createStrategy();
  const log = [], enemies = [], spawns = new Map(), multiplier = [0,1000];
  let wave = 0, gold = 250, baseHp = 10, nextId = 1, fallTick = -1;
  function draw() {
    seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed "'^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t;
    return (t ''^ (t >>> 14)) >>> 0;
  }
  function composition(w) {
    const eligible = types.filter(row => row[6] <= w);
    const weight = eligible.reduce((n,row) => n+row[7],0);
    return Array.from({length:4+Math.floor(3*w/5)}, () => {
      let r = draw() % weight;
      for (const row of eligible) {
        r -= row[7];
        if (r < 0) return row;
      }
    });
  }
  function locate(e) {
    const route = paths[e.air];
    let distance = e.progress;
    for (let i = 1; i < route.length; i++) {
      const [x,y] = route[i-1], [nx,ny] = route[i];
      const segment = Math.abs(nx-x)+Math.abs(ny-y);
      if (distance < segment || i === route.length-1) {
        e.x = x + Math.sign(nx-x)*distance;
        e.y = y + Math.sign(ny-y)*distance;
        e.dx = Math.sign(nx-x);
        e.dy = Math.sign(ny-y);
        return;
      }
      distance -= segment;
    }
  }
  function spawn(row,w,progress=0,hp=Math.floor(row[1]*multiplier[w]/1000)) {
    const [type,,speed,bounty,leak,air] = row;
    const armor = type === '"'grunt' ? Math.floor(w/4) : type === 'brute' ? 6+w : 0;
    const e = {id:nextId++,type,hp,maxHp:hp,speed,bounty,leak,air,armor,w,progress,slow:0,age:0};
    locate(e);
    enemies.push(e);
  }
  function view(e) {
    const {id,type,hp,maxHp,x,y,air,armor,speed,slow} = e;
    return {id,type,hp,maxHp,x,y,air,armor,speed,slowed:slow>0,remaining:lengths[air]-e.progress};
  }
  const distance2 = (a,b) => (a.x-b.x)**2+(a.y-b.y)**2;
  let next = composition(1);
  for (let tick = 0; tick < maxTicks; tick++) {
    const effects = record ? [] : null;
    const emit = (kind, data) => { if (effects) effects.push({kind,...data}); };
    if (tick >= 20 && (tick-20)%40 === 0) {
      wave++;
      gold += Math.min(50,Math.floor(gold*5/100))+10+2*wave;
      if (wave > 1) multiplier[wave] = Math.floor(multiplier[wave-1]*108/100);
      const current = next;
      next = composition(wave+1);
      emit('wave',{});
      const actions = strategy.plan({tick,wave,gold,baseHp,
        slots:slots.map(({slot,x,y,turret}) => ({slot,x,y,turret:turret && {type:turret.type,tier:turret.tier,spent:turret.spent}})),
        enemies:enemies.map(view),nextWave:next.map(row => row[0])});
      if (Array.isArray(actions)) for (const action of actions.slice(0,32)) {
        if ("'!action || !Number.isInteger(action.slot)) continue;
        const s = slots[action.slot];
        if (!s) continue;
        const t = s.turret;
        if (action.op === '"'build' && "'!t) {
          const typeIndex = names.indexOf(action.type), stats = weapons[typeIndex];
          if (!stats || gold < stats[0]) continue;
          gold -= stats[0];
          s.turret = {type:action.type,typeIndex,tier:1,spent:stats[0],damage:stats[1],range:stats[3],cooldown:0};
          log.push([tick,'"'B',s.slot,typeIndex]);
          emit('build',{x:s.x,y:s.y});
        } else if (action.op === 'upgrade' && t && t.tier < 3) {
          const cost = weapons[t.typeIndex][0]*t.tier;
          if (gold < cost) continue;
          gold -= cost;
          t.spent += cost;
          t.damage = Math.floor(t.damage*16/10);
          t.range += 30;
          log.push([tick,'U',s.slot,++t.tier]);
          emit('upgrade',{x:s.x,y:s.y});
        } else if (action.op === 'sell' && t) {
          gold += Math.floor(t.spent*70/100);
          s.turret = null;
          log.push([tick,'S',s.slot,0]);
          emit('sell',{x:s.x,y:s.y});
        }
      }
      current.forEach((row,i) => {
        const when = tick+4*i;
        if ("'!spawns.has(when)) spawns.set(when,[]);
        spawns.get(when).push([row,wave]);
      });
    }
    for (const [row,w] of spawns.get(tick) || []) spawn(row,w);
    spawns.delete(tick);
    for (let i = 0; i < enemies.length;) {
      const e = enemies[i];
      e.progress += e.slow > 0 ? Math.floor(e.speed*60/100) : e.speed;
      locate(e);
      if (e.progress < lengths[e.air]) { i++; continue; }
      enemies.splice(i,1);
      baseHp -= e.leak;
      log.push([tick,'"'L',e.id,baseHp]);
      emit('leak',{x:2350,y:1150});
      if (baseHp <= 0) {
        fallTick = tick;
        log.push([tick,'F',wave,0]);
        emit('fall',{x:2350,y:1150});
        break;
      }
    }
    if (fallTick < 0) {
      for (const e of enemies) if (++e.age % 20 === 0 && e.type === 'mender') {
        emit('heal',{x:e.x,y:e.y,radius:150});
        for (const other of enemies) if (distance2(e,other)<=22500) {
          other.hp = Math.min(other.maxHp,other.hp+Math.floor(other.maxHp*8/100));
        }
      }
      for (const s of slots) {
        const t = s.turret;
        if ("'!t) continue;
        if (t.cooldown > 0 && --t.cooldown > 0) continue;
        const [,,period,,radius,slow,pierce,domains] = weapons[t.typeIndex];
        const candidates = enemies.filter(e => (domains & (1<<e.air)) && distance2(e,s)<=t.range*t.range);
        if (!candidates.length) continue;
        const id = strategy.target?.({slot:s.slot,type:t.type,tier:t.tier,x:s.x,y:s.y,range:t.range},candidates.map(view));
        const chosen = candidates.find(e => e.id === id) || candidates.reduce((a,b) =>
          lengths[b.air]-b.progress < lengths[a.air]-a.progress ? b : a);
        emit('"'shot',{x:s.x,y:s.y,tx:chosen.x,ty:chosen.y,air:chosen.air,type:t.typeIndex,radius});
        for (const e of radius ? enemies : [chosen]) {
          if (radius && ("'!(domains & (1<<e.air)) || distance2(e,chosen)>radius*radius)) continue;
          e.hp -= Math.max(1,t.damage-(pierce ? 0 : e.armor));
          if (slow) e.slow = slow;
        }
        t.cooldown = period;
        for (let i = 0; i < enemies.length;) {
          const e = enemies[i];
          if (e.hp > 0) { i++; continue; }
          enemies.splice(i,1);
          gold += e.bounty;
          log.push([tick,'"'K',e.id,s.slot]);
          emit('kill',{x:e.x,y:e.y,air:e.air,type:e.type});
          if (e.type === 'splitter') for (let j = 0; j < 3; j++) {
            spawn(types[6],e.w,e.progress,Math.max(1,Math.floor(e.maxHp/4)));
          }
        }
      }
      for (const e of enemies) if (e.slow > 0) e.slow--;
    }
    if (record) record(tick,{wave,gold,baseHp,effects,next:next.map(row => row[0]),
      slots:slots.map(s => s.turret && [s.turret.typeIndex,s.turret.tier]),
      enemies:enemies.map(e => ({...view(e),dx:e.dx,dy:e.dy,progress:e.progress}))});
    if (fallTick >= 0) break;
  }
  let hash = 0x811c9dc5;
  const json = JSON.stringify(log);
  for (let i = 0; i < json.length; i++) hash = Math.imul(hash "'^ json.charCodeAt(i),0x01000193);
  const score = Math.round(((fallTick < 0 ? maxTicks : fallTick)-20)*2.5)/100;
  return {score,fallTick,log,hash:(hash>>>0).toString(16).padStart(8,'"'0')};
}
</script>
