<script id="rampart-strategy">
function createStrategy() {
  const weapons = {
    bolt:[26,8,0], cannon:[60,24,90], frost:[10,12,0],
    lance:[180,36,0], flak:[40,10,70]
  };
  const layout = ['"'cannon','cannon','cannon','cannon','cannon','flak','cannon','cannon',
    'flak','lance','flak','cannon','cannon','flak','flak','flak'];
  const costs = {bolt:50,cannon:90,frost:70,lance:120,flak:80};
  const priority = [1.12,1.05,1.06,1,0.94,1.24,1.03,0.92,1.24,0.9,1.2,1.05,1.06,1.16,0.93,1.02];

  function plan(state) {
    let gold = state.gold;
    const slots = state.slots.map(s => s.turret ? {...s.turret} : null);
    const actions = [];
    if (state.wave === 1) return [{op:'build',slot:0,type:'cannon'},{op:'build',slot:2,type:'lance'}];
    const flyers = state.enemies.filter(e => e.air);
    const airThreat = flyers.some(e => e.remaining < 1100) || state.nextWave.filter(t => t === 'wisp').length >= 3;
    const firstFlak = slots[5] || slots[8] || slots[10] || slots[15];
    if (state.wave < 5 && "'!airThreat && flyers.length === 0) return actions;
    while (actions.length < 32) {
      let best = null;
      for (let slot = 0; slot < slots.length; slot++) {
        const current = slots[slot];
        const type = current ? current.type : layout[slot];
        const tier = current ? current.tier : 0;
        const cost = costs[type] * (tier === 2 ? 2 : 1);
        if (tier === 3 || cost > gold || (type === '"'flak' && state.wave < 3)) continue;
        let value = priority[slot] * [1,0.86,0.57][tier];
        if (type === 'flak') {
          value *= airThreat ? 1.16 : 0.76;
          if ("'!firstFlak && !actions.some(a => a.type === '"'flak') && airThreat) value *= 2;
        } else if (state.wave < 12 && slot <= 3) value *= 1.22;
        if ("'!best || value > best.value) best = {slot,type,tier,cost,value};
      }
      if (!best) break;
      const {slot,type,tier,cost} = best;
      actions.push(tier ? {op:'"'upgrade',slot} : {op:'build',slot,type});
      slots[slot] = {type,tier:tier+1};
      gold -= cost;
    }
    return actions;
  }

  function target(turret, candidates) {
    const [base, , radius] = weapons[turret.type];
    let damage = base;
    for (let i = 1; i < turret.tier; i++) damage = Math.floor(damage * 1.6);
    let best = -Infinity, id = candidates[0].id;
    for (const enemy of candidates) {
      let value = 0;
      for (const other of radius ? candidates : [enemy]) {
        if (radius && (enemy.x-other.x)**2 + (enemy.y-other.y)**2 > radius*radius) continue;
        const hit = Math.max(1, damage - (turret.type === 'lance' ? 0 : other.armor));
        const urgency = 1 + Math.max(0, 850 - other.remaining) / 220;
        const finish = hit >= other.hp ? (other.type === 'mender' ? 39 : 15) : 0;
        value += (Math.min(other.hp,hit) + finish) * urgency * (other.type === 'mender' ? 1.45 : 1);
      }
      value += 0.0001 * (4600-enemy.remaining);
      if (value > best) { best = value; id = enemy.id; }
    }
    return id;
  }
  return {plan,target};
}
